{
  "vulnerabilidade_identificada": "Cross-site scripting (XSS) armazenado ao exibir comentários de feedback na galeria.",
  "causa_da_vulnerabilidade": "O comentário, que pode ser controlado por um usuário, é interpolado diretamente em uma string HTML e essa string é marcada como confiável por `bypassSecurityTrustHtml`, desativando a sanitização do Angular. Um comentário malicioso pode, assim, ser interpretado como HTML ativo.",
  "estrategia_de_correcao": "Escapar os caracteres especiais de HTML do comentário antes de inseri-lo na marcação e manter a estrutura existente da galeria. Não marcar o HTML resultante como confiável; deixar o Angular sanitizá-lo normalmente.",
  "edicoes": [
    {
      "arquivo": "frontend/src/app/about/about.component.ts",
      "trecho_original": "          feedbacks[i].comment = `<figcaption><p class="feedback-comment">${
            feedbacks[i].comment
          }</p><div class="feedback-stars">(${this.stars[feedbacks[i].rating]})</div></figcaption>`
          feedbacks[i].comment = this.sanitizer.bypassSecurityTrustHtml(
            feedbacks[i].comment
          )",
      "trecho_corrigido": "          const escapedComment = feedbacks[i].comment.replace(/[&<>"']/g, (character) => {
            const entities: Record<string, string> = {
              '&': '&amp;',
              '<': '&lt;',
              '>': '&gt;',
              '"': '&quot;',
              "'": '&#39;'
            }
            return entities[character]
          })
          feedbacks[i].comment = `<figcaption><p class="feedback-comment">${
            escapedComment
          }</p><div class="feedback-stars">(${this.stars[feedbacks[i].rating]})</div></figcaption>`"
    }
  ],
  "justificativa_tecnica": "O escape de `&`, `<`, `>`, aspas duplas e apóstrofos impede que o conteúdo do comentário crie elementos ou atributos HTML. A remoção de `bypassSecurityTrustHtml` evita desativar a proteção do Angular; a sanitização padrão continua aplicada ao HTML da galeria. A marcação e as estrelas permanecem funcionais.",
  "limitacoes_da_correcao": "A correção protege o comentário neste ponto de renderização. Outros locais que exibam comentários ou conteúdo não confiável precisam ser avaliados separadamente."
}
